import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        a = int(next(iterator))
        b = int(next(iterator))

        chars = [chr(ord('a') + i) for i in range(26)]
        result = []

        for i in range(n):
            if i < a:
                if i < b:
                    result.append(chars[i])
                else:
                    result.append(chars[i % b])
            else:
                prev_char = result[-1]
                window_start_idx = i - a

                if window_start_idx >= 0:
                    char_to_remove = result[window_start_idx]
                    current_window = result[window_start_idx:i]

                    unique_in_window = set(current_window)

                    if len(unique_in_window) == b:
                        if char_to_remove in unique_in_window:
                            count_of_removed = current_window.count(char_to_remove)
                            if count_of_removed == 1:
                                new_char = char_to_remove
                            else:
                                for c in chars:
                                    if c != char_to_remove and c not in unique_in_window:
                                        new_char = c
                                        break
                                else:
                                    new_char = chars[0]
                        else:
                            new_char = char_to_remove
                    else:
                        for c in chars:
                            if c != char_to_remove and c not in unique_in_window:
                                new_char = c
                                break
                        else:
                            new_char = chars[0]
                else:
                    new_char = chars[0]

                result.append(new_char)

        results.append("".join(result))

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
